package database

import (
	"compress/gzip"
	"io"
	"os"
	"reflect"
	"testing"

	"yingce/backend/internal/model"
)

// The fixture is generated by the schema 107 production source, before merging
// upstream models. It contains only synthetic users, balances, tasks and drafts.
func TestV187UpgradePreservesProduction107DataAndLedger(t *testing.T) {
	fixture, err := os.Open("testdata/production107.sql.gz")
	if err != nil {
		t.Fatal(err)
	}
	defer fixture.Close()
	reader, err := gzip.NewReader(fixture)
	if err != nil {
		t.Fatal(err)
	}
	defer reader.Close()
	sql, err := io.ReadAll(reader)
	if err != nil {
		t.Fatal(err)
	}
	db, err := Open(Config{Driver: "sqlite", DSN: "file:v187-production107?mode=memory&cache=shared"})
	if err != nil {
		t.Fatal(err)
	}
	conn, err := db.DB()
	if err != nil {
		t.Fatal(err)
	}
	defer conn.Close()
	if err := db.Exec(string(sql)).Error; err != nil {
		t.Fatal(err)
	}
	var before []schemaMigration
	if err := db.Order("version").Find(&before).Error; err != nil {
		t.Fatal(err)
	}
	if len(before) == 0 || before[len(before)-1].Version != 107 {
		t.Fatal("fixture is not schema 107")
	}
	if db.Migrator().HasTable(&model.Team{}) {
		t.Fatal("fixture already contains upstream team schema")
	}
	for range 2 {
		if err := MigrateSchema(db); err != nil {
			t.Fatal(err)
		}
	}
	var after []schemaMigration
	if err := db.Order("version").Find(&after).Error; err != nil {
		t.Fatal(err)
	}
	if len(after) != len(before)+11 || !reflect.DeepEqual(after[:len(before)], before) {
		t.Fatal("published production ledger was rewritten")
	}
	status, err := ReadSchemaStatus(db)
	if err != nil || !status.Ready || status.Current != 118 {
		t.Fatalf("schema=%+v err=%v", status, err)
	}
	var account model.CreditAccount
	if err := db.First(&account, "user_id = ?", "upgrade-user").Error; err != nil || account.ID != model.PersonalCreditAccountID("upgrade-user") || account.AvailableMicrocredits != 432100 || account.ReservedMicrocredits != 12300 || account.Version != 7 {
		t.Fatalf("account=%+v err=%v", account, err)
	}
	var order model.BillingOrder
	if err := db.First(&order, "id = ?", "upgrade-order").Error; err != nil || order.BillingAccountID != account.ID || !order.DeductedUpfront || order.Status != model.BillingStatusRunning || order.AmountMicrocredits != 2500 {
		t.Fatalf("order=%+v err=%v", order, err)
	}
	var ledger model.CreditLedgerEntry
	if err := db.First(&ledger, "id = ?", "upgrade-ledger").Error; err != nil || ledger.AccountID != account.ID || ledger.AmountMicrocredits != -2500 || ledger.AvailableAfterMicrocredits != 432100 {
		t.Fatalf("ledger=%+v err=%v", ledger, err)
	}
	var task model.Task
	if err := db.First(&task, "id = ?", "upgrade-task").Error; err != nil || task.Status != "running" || task.BillingOrderID != order.ID {
		t.Fatalf("task=%+v err=%v", task, err)
	}
	var draft model.EcommerceProject
	if err := db.First(&draft, "id = ?", "upgrade-shop").Error; err != nil || draft.DraftJSON != `{"custom":true}` || draft.Revision != 4 {
		t.Fatalf("draft=%+v err=%v", draft, err)
	}
	for _, table := range []any{&model.Team{}, &model.SiteTrafficEvent{}, &model.CreationConversation{}} {
		if !db.Migrator().HasTable(table) {
			t.Fatalf("new schema missing %T", table)
		}
	}
}
